// Calculate per-workflow metrics
const executions = $input.first().json.data || [];
const now = new Date();
const oneDayAgo = new Date(now - 24 * 60 * 60 * 1000);
const sevenDaysAgo = new Date(now - 7 * 24 * 60 * 60 * 1000);

// Group executions by workflow
const workflowMetrics = {};

for (const exec of executions) {
  const workflowName = exec.workflowData?.name || 'Unknown';
  const workflowId = exec.workflowId;
  const startedAt = new Date(exec.startedAt);
  const stoppedAt = exec.stoppedAt ? new Date(exec.stoppedAt) : null;
  const duration = stoppedAt ? (stoppedAt - startedAt) : null;
  const isSuccess = exec.finished && !exec.error;
  const isLast24h = startedAt >= oneDayAgo;
  const isLast7d = startedAt >= sevenDaysAgo;

  if (!workflowMetrics[workflowId]) {
    workflowMetrics[workflowId] = {
      name: workflowName,
      id: workflowId,
      total24h: 0,
      success24h: 0,
      failed24h: 0,
      total7d: 0,
      success7d: 0,
      failed7d: 0,
      avgDuration: [],
      errors: []
    };
  }

  if (isLast24h) {
    workflowMetrics[workflowId].total24h++;
    if (isSuccess) {
      workflowMetrics[workflowId].success24h++;
    } else {
      workflowMetrics[workflowId].failed24h++;
      if (exec.error) {
        workflowMetrics[workflowId].errors.push({
          message: exec.error.message?.substring(0, 100),
          time: exec.startedAt
        });
      }
    }
  }

  if (isLast7d) {
    workflowMetrics[workflowId].total7d++;
    if (isSuccess) {
      workflowMetrics[workflowId].success7d++;
    } else {
      workflowMetrics[workflowId].failed7d++;
    }
    if (duration) {
      workflowMetrics[workflowId].avgDuration.push(duration);
    }
  }
}

// Calculate final metrics
const results = Object.values(workflowMetrics).map(wf => {
  const successRate24h = wf.total24h > 0 
    ? ((wf.success24h / wf.total24h) * 100).toFixed(1) 
    : 'N/A';
  const successRate7d = wf.total7d > 0 
    ? ((wf.success7d / wf.total7d) * 100).toFixed(1) 
    : 'N/A';
  const avgDuration = wf.avgDuration.length > 0
    ? (wf.avgDuration.reduce((a, b) => a + b, 0) / wf.avgDuration.length / 1000).toFixed(2) + 's'
    : 'N/A';

  return {
    name: wf.name,
    id: wf.id,
    successRate24h: successRate24h + '%',
    successRate7d: successRate7d + '%',
    executions24h: wf.total24h,
    executions7d: wf.total7d,
    failed24h: wf.failed24h,
    avgDuration,
    recentErrors: wf.errors.slice(0, 3)
  };
}).sort((a, b) => b.executions24h - a.executions24h);

// Check for anomalies (success rate < 90%)
const anomalies = results.filter(r => {
  const rate = parseFloat(r.successRate24h);
  return !isNaN(rate) && rate < 90;
});

return {
  json: {
    timestamp: now.toISOString(),
    metrics: results,
    anomalies,
    hasAnomalies: anomalies.length > 0
  }
};

